## Facade Pattern

## Intent

Provide a simplified interface to a complex subsystem, shielding the caller from its details.

## API Service Layer Facade

```typescript
// Without facade — caller manages everything
async function loginUser(email: string, password: string) {
  const res = await fetch('/api/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error(await res.text());
  const { token, refreshToken } = await res.json();
  localStorage.setItem('token', token);
  localStorage.setItem('refreshToken', refreshToken);
  scheduleTokenRefresh(token);
  analytics.track('user_login');
}

// With facade — caller sees one clean method
class AuthService {
  async login(email: string, password: string): Promise<User> {
    const { token, refreshToken, user } = await this.post('/auth/login', { email, password });
    this.tokenStore.save(token, refreshToken);
    this.refreshScheduler.schedule(token);
    this.analytics.track('user_login');
    return user;
  }

  async logout(): Promise<void> { /* hides token revocation + cache clearing */ }
  async refreshSession(): Promise<void> { /* hides refresh token flow */ }

  private post(path: string, body: unknown) { /* hides fetch + error handling */ }
}

export const authService = new AuthService();
// Callers: authService.login(email, password)
```

## Custom Hook as Facade

```typescript
// Without facade — component manages query details
function ProductList() {
  const { data, isLoading, error } = useQuery({
    queryKey: ['products', { category: 'electronics', page: 1 }],
    queryFn: () => api.get('/products?category=electronics&page=1'),
    staleTime: 5 * 60 * 1000,
    select: (data) => data.items.map(normaliseProduct),
  });
  // ...
}

// With facade — clean abstraction
function useProducts(category: string, page: number) {
  return useQuery({
    queryKey: ['products', { category, page }],
    queryFn: () => api.get(`/products?category=${category}&page=${page}`),
    staleTime: 5 * 60 * 1000,
    select: (data) => data.items.map(normaliseProduct),
  });
}

function ProductList() {
  const { data, isLoading, error } = useProducts('electronics', 1);
  // Component is now decoupled from query internals
}
```

## Supabase Client Facade

```typescript
// Wrap the raw Supabase client behind a typed facade
class UserRepository {
  async findById(id: string): Promise<User | null> {
    const { data, error } = await supabase
      .from('users').select().eq('id', id).single();
    if (error) throw new AppError('USER_NOT_FOUND', error.message);
    return data;
  }
}
// Callers never know Supabase is involved
```

## Facade vs Adapter

```
Facade:  simplifies a complex interface (internal)
Adapter: translates between incompatible interfaces (external)
```

## Adapter Pattern

## Intent

Convert the interface of a class into another interface that clients expect, enabling incompatible interfaces to work together.

## Data Normalisation Adapter

```typescript
// Third-party API returns inconsistent shape
interface LegacyUser {
  first_name: string;
  last_name: string;
  email_address: string;
  date_of_birth: string; // 'DD/MM/YYYY'
}

// Your app expects
interface User {
  fullName: string;
  email: string;
  age: number;
}

// Adapter
function adaptLegacyUser(legacy: LegacyUser): User {
  const [day, month, year] = legacy.date_of_birth.split('/').map(Number);
  const dob = new Date(year, month - 1, day);
  const age = Math.floor((Date.now() - dob.getTime()) / (365.25 * 24 * 60 * 60 * 1000));

  return {
    fullName: `${legacy.first_name} ${legacy.last_name}`,
    email: legacy.email_address,
    age,
  };
}

// Your app only ever sees User — unaware of LegacyUser
const users: User[] = rawData.map(adaptLegacyUser);
```

## Library Migration Adapter

```typescript
// Migrating from Axios to fetch — adapter keeps the call sites unchanged

// Old interface (Axios-style)
interface HttpClient {
  get<T>(url: string, config?: { params?: Record<string, string> }): Promise<T>;
  post<T>(url: string, data: unknown): Promise<T>;
}

// Adapter: fetch behaves like Axios
class FetchAdapter implements HttpClient {
  async get<T>(url: string, config?: { params?: Record<string, string> }): Promise<T> {
    const search = config?.params ? '?' + new URLSearchParams(config.params) : '';
    const res = await fetch(url + search);
    if (!res.ok) throw new Error(res.statusText);
    return res.json();
  }

  async post<T>(url: string, data: unknown): Promise<T> {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    if (!res.ok) throw new Error(res.statusText);
    return res.json();
  }
}

// All existing call sites remain unchanged
const http: HttpClient = new FetchAdapter();
const users = await http.get<User[]>('/api/users', { params: { active: 'true' } });
```

