## Behavioral Patterns

### State Pattern → useReducer

```typescript
// Explicit state machine — each state allows only valid transitions
type AuthState = { status: 'idle' } | { status: 'loading' } | { status: 'authenticated'; user: User } | { status: 'error'; message: string };

function authReducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case 'LOGIN_START': return { status: 'loading' };
    case 'LOGIN_SUCCESS': return { status: 'authenticated', user: action.user };
    case 'LOGIN_ERROR': return { status: 'error', message: action.message };
    default: return state;
  }
}
```

### Observer → Context API

```typescript
// ThemeContext = Subject; consumers = Observers
const ThemeContext = createContext<Theme>('light');

// Any consumer re-renders when the value changes — Observer notification
function ThemeToggle() {
  const theme = useContext(ThemeContext); // subscribes
  return <button>{theme === 'light' ? '🌙' : '☀️'}</button>;
}
```

### Strategy → Interchangeable Hook Logic

```typescript
// Swap validation strategy per form type
const emailValidator = (v: string) => /^[^@]+@[^@]+/.test(v);
const phoneValidator = (v: string) => /^\+?\d{10,}$/.test(v);

function useField(strategy: (v: string) => boolean) {
  const [value, setValue] = useState('');
  const isValid = strategy(value);
  return { value, setValue, isValid };
}

const emailField = useField(emailValidator);
const phoneField = useField(phoneValidator);
```
